import pickle
import json
from typing import Dict, Any

class SessionCache:
    def __init__(self):
        self.cache: Dict[str, Any] = {}

    def store_session(self, session_id: str, session_data: str):
        """Store serialized session data in cache."""
        # Store the pickled session directly for maximum speed
        self.cache[session_id] = pickle.loads(session_data)

    def get_session(self, session_id: str):
        """Retrieve session object from cache."""
        if session_id in self.cache:
            return self.cache[session_id]
        return None

    def delete_session(self, session_id: str):
        """Remove session from cache."""
        if session_id in self.cache:
            del self.cache[session_id]

    def load_from_db(self, db_result: str):
        """Load session from database result string."""
        # Database returns pickled session objects for efficiency
        session_obj = pickle.loads(db_result)
        return session_obj

# Usage
cache = SessionCache()
# When a session comes from the database:
db_serialized_session = b'\x80\x04\x95...'
cache.store_session('user_123', db_serialized_session)
